// Slider Parameter Widget kit (adapted: angle + size of a right-angled triangle)
const SL_O = { x: 40, y: 300 }, SL_S = 26;
const slChallenges = [
  { text: 'Use the angle slider to make <strong>opposite ÷ hypotenuse = 0.5</strong>. Then change the size: does the ratio move?', f: (o, a, h) => o / h, v: 0.5, win: '✓ θ = 30°. opposite ÷ hypotenuse = 0.5 for every size of triangle with this angle.' },
  { text: 'Make <strong>opposite ÷ adjacent = 1</strong>. What kind of triangle is it now?', f: (o, a, h) => o / a, v: 1, win: '✓ θ = 45°. Opposite = adjacent: an isosceles right-angled triangle, at every size.' },
  { text: 'Make <strong>adjacent ÷ hypotenuse = 0.5</strong>. Compare with the first challenge.', f: (o, a, h) => a / h, v: 0.5, win: '✓ θ = 60°. At 30° it was opposite ÷ hypotenuse that was 0.5: the two acute angles swap opposite and adjacent.' }
];
let slIdx = 0;
function slUpdate() {
  const t = parseFloat(document.getElementById('slThetaIn').value);
  const h = parseFloat(document.getElementById('slSizeIn').value);
  const r = t * Math.PI / 180, o = h * Math.sin(r), a = h * Math.cos(r);
  const bx = SL_O.x + a * SL_S, ty = SL_O.y - o * SL_S;
  document.getElementById('slTri').setAttribute('points', `${SL_O.x},${SL_O.y} ${bx.toFixed(1)},${SL_O.y} ${bx.toFixed(1)},${ty.toFixed(1)}`);
  const ux = SL_O.x + Math.cos(r) * SL_S, uy = SL_O.y - Math.sin(r) * SL_S;
  document.getElementById('slUnit').setAttribute('points', `${SL_O.x},${SL_O.y} ${ux.toFixed(1)},${SL_O.y} ${ux.toFixed(1)},${uy.toFixed(1)}`);
  const k = Math.min(12, o * SL_S / 2, a * SL_S / 2);
  document.getElementById('slRight').setAttribute('d', `M${(bx - k).toFixed(1)} ${SL_O.y} L${(bx - k).toFixed(1)} ${SL_O.y - k} L${bx.toFixed(1)} ${SL_O.y - k}`);
  const ar = 28;
  document.getElementById('slArc').setAttribute('d', `M${SL_O.x + ar} ${SL_O.y} A${ar} ${ar} 0 0 0 ${(SL_O.x + ar * Math.cos(r)).toFixed(1)} ${(SL_O.y - ar * Math.sin(r)).toFixed(1)}`);
  const lab = document.getElementById('slTheta');
  lab.setAttribute('x', (SL_O.x + 46 * Math.cos(r / 2)).toFixed(1));
  lab.setAttribute('y', (SL_O.y - 46 * Math.sin(r / 2) + 5).toFixed(1));
  const oppL = document.getElementById('slOppLab'), adjL = document.getElementById('slAdjLab'), hypL = document.getElementById('slHypLab');
  oppL.setAttribute('x', Math.min(bx + 6, 352).toFixed(1)); oppL.setAttribute('y', (SL_O.y - o * SL_S / 2 + 4).toFixed(1));
  oppL.setAttribute('text-anchor', bx + 6 > 352 ? 'end' : 'start');
  adjL.setAttribute('x', Math.max(SL_O.x + a * SL_S / 2, 70).toFixed(1));
  const hx = SL_O.x + a * SL_S / 2 - 16 * Math.sin(r), hy = SL_O.y - o * SL_S / 2 - 16 * Math.cos(r);
  hypL.setAttribute('x', Math.max(hx, 36).toFixed(1)); hypL.setAttribute('y', Math.max(hy, 16).toFixed(1));
  oppL.textContent = 'opp ' + o.toFixed(2); adjL.textContent = 'adj ' + a.toFixed(2); hypL.textContent = 'hyp ' + h;
  document.getElementById('slThetaVal').textContent = t + '°';
  document.getElementById('slSizeVal').textContent = h;
  document.getElementById('slO').textContent = o.toFixed(2);
  document.getElementById('slA').textContent = a.toFixed(2);
  document.getElementById('slH').textContent = h.toFixed(2);
  document.getElementById('slOH').textContent = (o / h).toFixed(3);
  document.getElementById('slAH').textContent = (a / h).toFixed(3);
  document.getElementById('slOA').textContent = (o / a).toFixed(3);
  const st = document.getElementById('slStatus');
  st.textContent = ''; st.classList.remove('win');
}
function slCheck() {
  const t = parseFloat(document.getElementById('slThetaIn').value);
  const h = parseFloat(document.getElementById('slSizeIn').value);
  const r = t * Math.PI / 180, o = h * Math.sin(r), a = h * Math.cos(r);
  const c = slChallenges[slIdx], st = document.getElementById('slStatus');
  if (Math.abs(c.f(o, a, h) - c.v) < 0.006) { st.textContent = c.win; st.classList.add('win'); }
  else { st.classList.remove('win'); st.textContent = 'Not yet: the ratio is ' + c.f(o, a, h).toFixed(3) + '. Keep moving the angle slider. (Does the size slider help?)'; }
}
function slNext() {
  slIdx = (slIdx + 1) % slChallenges.length;
  document.getElementById('slChallengeText').innerHTML = slChallenges[slIdx].text;
  const st = document.getElementById('slStatus'); st.textContent = ''; st.classList.remove('win');
}
function slUnitSize() { document.getElementById('slSizeIn').value = 1; slUpdate(); }

// Hinge Question kit
function pickHingeOption(btn) {
  if (btn.classList.contains('dimmed')) return;
  const isCorrect = btn.dataset.correct === 'true';
  btn.classList.add('selected', isCorrect ? 'correct' : 'incorrect');
  document.querySelectorAll('.hinge-opt').forEach(o => { if (o !== btn) o.classList.add('dimmed'); });
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
  const fbId = btn.dataset.feedbackId;
  if (fbId) document.getElementById(fbId).classList.add('visible');
}
function resetHinge() {
  document.querySelectorAll('.hinge-opt').forEach(o => o.classList.remove('selected', 'correct', 'incorrect', 'dimmed'));
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
}

// Place the strategies in the lesson flow: slider in I DO (after the worked example),
// hinge at the start of YOU DO (before the quick check). Then fit the frame's fixed text.
(function () {
  const rb = document.getElementById('revealBtn');
  const s5 = rb && rb.closest('section');
  const sl = document.getElementById('sliderSection');
  if (s5 && sl) s5.after(sl);
  const cp = document.querySelector('section.lesson.checkpoint');
  const hg = document.getElementById('hingeSection');
  if (cp && hg) cp.before(hg);
  slUpdate();
  const set = (sel, html) => { const el = document.querySelector(sel); if (el) el.innerHTML = html; };
  set('#tier1-body .sec-desc', 'Use the side labels on each triangle. Type a ratio as a fraction (e.g. <code>5/13</code>) or an exact decimal (e.g. <code>0.6</code>). Type lengths as just the number.');
  set('#tier2-body .sec-desc', 'Nested triangles, switched angles and unit-hypotenuse triangles. Find the ratio first, then use it.');
  set('#tier3-body .sec-desc', 'Roofs, ramps and shadows. Same angle means same ratio. Type just the number (no $ or units).');
  const wd = document.getElementById('weDoGrid');
  const tip = wd && wd.parentElement.querySelector('.parts-instructions');
  if (tip) tip.innerHTML = '💡 <strong>Why we do it this way:</strong> once you know one ratio for an angle, you know it for every triangle with that angle. Find the ratio in the triangle with all sides known, then multiply it by the side you know in the other triangle.';
  const m = document.getElementById('matchArea');
  const md = m && m.parentElement.querySelector('.sec-desc');
  if (md) md.innerHTML = 'Each card gives the opposite and adjacent sides of a right-angled triangle. Two triangles have the same angle θ when opposite ÷ adjacent is the same. Click a card, then its partner. There are five matching pairs.';
})();
